def prime_factorization(num):
    factors = {}
    d = 2
    temp = num
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def check_divisibility(n):
    # Calculate D(n) = n^3 + 4n^2 + 6n + 4
    D_n = n**3 + 4*n**2 + 6*n + 4

    # Handle the trivial case D(n) = 0 (though for n>=0, D(n) >= 4)
    if D_n == 0:
        return False, {}

    # Prime factorization of D(n)
    factors_D_n = prime_factorization(D_n)

    # The condition is that D(n) divides 20^(n+1) = (2^2 * 5)^(n+1) = 2^(2n+2) * 5^(n+1)

    # Prime factors of 20^(n+1) are only 2 and 5.
    for p, power in factors_D_n.items():
        if p != 2 and p != 5:
            # D(n) has a prime factor other than 2 or 5, so it cannot divide 20^(n+1)
            return False, factors_D_n

        if p == 2:
            # Check power of 2
            max_power_2 = 2 * n + 2
            if power > max_power_2:
                return False, factors_D_n
        elif p == 5:
            # Check power of 5
            max_power_5 = n + 1
            if power > max_power_5:
                return False, factors_D_n

    # If we reach here, D(n) divides 20^(n+1)
    return True, factors_D_n

solutions = []
for n in range(16): # Check n from 0 up to 15
    is_solution, factors = check_divisibility(n)

    if is_solution:
        solutions.append(n)

    print(f"n={n}: Divisible? {is_solution}. Factorization of D({n}): {factors}")

print(f"\nSolutions found (0 <= n <= 15): {solutions}")

