def check_2_5_factors(k):
    if k == 0:
        return True # Or False, but D(n) > 0 for n >= 0

    temp = k
    while temp > 1:
        if temp % 2 == 0:
            temp //= 2
        elif temp % 5 == 0:
            temp //= 5
        else:
            return False
    return True

def D(n):
    # D(n) = n^3 + 4n^2 + 6n + 4
    return n**3 + 4*n**2 + 6*n + 4

print("--- Checking D(n) for factors only 2 and 5 ---")
candidates = []
limit = 50 # Search up to n=50

for n in range(limit + 1):
    d_n = D(n)
    if check_2_5_factors(d_n):
        candidates.append(n)
        print(f"n={n}: D(n)={d_n} (Candidate)")

print("\nCandidates found:", candidates)
